/**
 * ParallaxHelper - Helper class for parallax scrolling effects
 *
 * Creates parallax scrolling effects by moving background layers
 * at different speeds relative to camera movement.
 *
 * **Usage**
 *
 * Layers with lower factors move slower (distant backgrounds),
 * layers with higher factors move faster (foreground elements).
 *
 * - Factor 0.0 = no movement (fixed to screen)
 * - Factor 0.5 = moves at half camera speed (mid-ground)
 * - Factor 1.0 = moves with camera (no parallax, same as default)
 *
 * @class ParallaxHelper
 * @short Helper for parallax scrolling with configurable layer speeds.
 * @category Camera
 * @tags Parallax, 2D, Background, WebGPU, WebGL
 *
 * @example
 * ```js
 * import { ParallaxHelper } from '@three-blocks/pro';
 *
 * // Create parallax helper
 * const parallax = new ParallaxHelper(camera);
 *
 * // Add background layers with different speeds
 * parallax.addLayer(skyMesh, 0.1);      // Slow - distant sky
 * parallax.addLayer(mountainsMesh, 0.3); // Medium - mountains
 * parallax.addLayer(treesMesh, 0.6);    // Faster - trees
 *
 * // Set reference point (usually camera start position)
 * parallax.setReference(camera.position.x, camera.position.y);
 *
 * // In animation loop
 * parallax.update();
 * ```
 */
export class ParallaxHelper {
    /**
     * Create a ParallaxHelper.
     *
     * @param {THREE.Camera} camera - Camera to track for parallax
     */
    constructor(camera: THREE.Camera);
    /**
     * Reference to the camera.
     * @type {THREE.Camera}
     */
    camera: THREE.Camera;
    /**
     * Parallax layers with their settings.
     * @type {Array<{object: THREE.Object3D, factor: number, axis: string, startX: number, startY: number}>}
     * @private
     */
    private _layers;
    /**
     * Camera reference X position.
     * @type {number}
     * @private
     */
    private _cameraStartX;
    /**
     * Camera reference Y position.
     * @type {number}
     * @private
     */
    private _cameraStartY;
    /**
     * Add a layer to the parallax effect.
     *
     * @param {THREE.Object3D} object - Object to apply parallax to
     * @param {number} factor - Parallax factor (0 = fixed, 1 = moves with camera)
     * @param {string} [axis='xy'] - Axis to apply parallax: 'x', 'y', or 'xy'
     * @returns {this} For chaining
     *
     * @example
     * // Background that moves at 10% of camera speed
     * parallax.addLayer(skyBackground, 0.1);
     *
     * // Foreground that moves at 80% of camera speed
     * parallax.addLayer(nearTrees, 0.8, 'x'); // Only X-axis
     */
    addLayer(object: THREE.Object3D, factor: number, axis?: string): this;
    /**
     * Remove a layer from the parallax effect.
     *
     * @param {THREE.Object3D} object - Object to remove
     * @returns {this} For chaining
     */
    removeLayer(object: THREE.Object3D): this;
    /**
     * Set the reference position for parallax calculation.
     * Parallax offset is calculated relative to this position.
     * Call this at the start of the level or when resetting.
     *
     * @param {number} x - Reference X position (usually camera start X)
     * @param {number} y - Reference Y position (usually camera start Y)
     * @returns {this} For chaining
     */
    setReference(x: number, y: number): this;
    /**
     * Update all parallax layers based on camera position.
     * Call this in your animation loop after camera.update().
     *
     * @returns {this} For chaining
     */
    update(): this;
    /**
     * Get all registered layers.
     *
     * @returns {Array<{object: THREE.Object3D, factor: number, axis: string}>} Layer array
     */
    getLayers(): Array<{
        object: THREE.Object3D;
        factor: number;
        axis: string;
    }>;
    /**
     * Clear all parallax layers.
     *
     * @returns {this} For chaining
     */
    clear(): this;
    /**
     * Clean up resources.
     */
    dispose(): void;
}
